{"path": "api/me_views_test.go", "old": "", "new": "package api_test

import (
	"net/http"
	"testing"
)

// The read-only views of the caller's own data must require a token, like
// every other /v1/me route. Without it, the handlers dereference a nil user.
func TestExportAndStatsRequireToken(t *testing.T) {
	c := newClient(t)
	for _, path := range []string{"/v1/me/export", "/v1/me/stats"} {
		if code := c.do("", http.MethodGet, path, "", nil); code != http.StatusUnauthorized {
			t.Errorf("GET %s without token: status %d, want 401", path, code)
		}
	}
	for _, path := range []string{"/v1/me/export", "/v1/me/stats"} {
		if code := c.do("tok-ana", http.MethodGet, path, "", nil); code != http.StatusOK {
			t.Errorf("GET %s with token: status %d, want 200", path, code)
		}
	}
}
"}

